cd /app && python - <<'PY'
import cv2,numpy as np
cap=cv2.VideoCapture('example_video.mp4')
frames=[]
while True:
 ok,f=cap.read()
 if not ok: break
 frames.append(f)
patches={'top_left':(0,0,150,100),'track_low':(400,450,500,520),'mid':(400,250,500,300),'sky':(400,0,500,40)}
for i,f in enumerate(frames):
 if i%5==0 or 30<=i<=50:
  vals=[]
  for n,(x1,y1,x2,y2) in patches.items():
   vals.append(f"{n}={f[y1:y2,x1:x2].mean():.1f}")
  print(i,' '.join(vals))
PY
